import "fmt"

type Point struct{ X int }

func (p *Point) MoveX(dx int) { p.X += dx }
func (p Point) GetX() int     { return p.X }

func main() {
	// 1. Авто-взятие адреса (&p).MoveX(5):
	p := Point{X: 1}
	p.MoveX(5)
	fmt.Println("После MoveX:", p.GetX())

	// 2. Авто-разыменование (*pPtr).GetX():
	pPtr := &Point{X: 100}
	fmt.Println("GetX через указатель:", pPtr.GetX())
}

package main

import (
	"errors"
	"fmt"
)

type Account struct{ Balance float64 }

func (a *Account) Withdraw(amt float64) error {
	if amt > a.Balance { return errors.New("недостаточно средств") }
	a.Balance -= amt
	return nil
}

type CreditAccount struct {
	Account
	CreditLimit float64
}

func (c *CreditAccount) Withdraw(amt float64) error {
	if amt > c.Balance+c.CreditLimit {
		return fmt.Errorf("превышен кредитный лимит (доступно %.2f)", c.Balance+c.CreditLimit)
	}
	c.Balance -= amt
	return nil
}

func main() {
	ca := &CreditAccount{Account: Account{Balance: 100}, CreditLimit: 500}
	_ = ca.Withdraw(400)
	fmt.Printf("Баланс после овердрафта: %.2f руб.\n", ca.Balance)
}

package main

import (
	"fmt"
	"io"
)

type ReadWriteCloser interface {
	io.Reader
	io.Writer
	io.Closer
}

type MockFileSession struct {
	closed bool
}

func (m *MockFileSession) Read(p []byte) (int, error)  { return 0, io.EOF }
func (m *MockFileSession) Write(p []byte) (int, error) { return len(p), nil }
func (m *MockFileSession) Close() error                 { m.closed = true; return nil }

func main() {
	var rwc ReadWriteCloser = &MockFileSession{}
	_, _ = rwc.Write([]byte("лог"))
	_ = rwc.Close()
	fmt.Println("Сессия закрыта успешно!")
}

package main

import (
	"fmt"
	"io"
	"strings"
)

type LoggingReader struct {
	io.Reader // Встроенный Reader
}

func (l *LoggingReader) Read(p []byte) (int, error) {
	n, err := l.Reader.Read(p)
	fmt.Printf("[LOG]: Прочитано %d байт\n", n)
	return n, err
}

func main() {
	src := strings.NewReader("Go OOP Exercises")
	lr := &LoggingReader{Reader: src}
	out := make([]byte, 8)
	_, _ = lr.Read(out)
	fmt.Printf("Данные: %q\n", string(out))
}

